// === Tab: Circles ===
class Circle {
  constructor(x, y, r, hue) {
    this.x = x;
    this.y = y;
    this.r = r;
    this.hue = hue;
    this.isgrowing = true;
  }
	show() {
		fill(this.hue);
    noStroke();
    ellipse(this.x, this.y, this.r * 2);
	}
  grow() {
    this.r += .5;

  }
  touchesedges() {
    if (this.x - this.r < 0 || this.x + this.r > width || this.y + this.r > height || this.y - this.r < 0) {
      this.isgrowing=false;
    }
  }
  touchesother(other) {
    let d = dist(this.x, this.y, other.x, other.y);
    if (d < (this.r + other.r)) {
      this.r-=1;
      this.isgrowing = false;
    }
  }

}

