var circles = [];
var img;
var list = [];
var radius;

function preload() {
	img = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/alex.jpg');
}

function setup() {
	img.resize(windowHeight, 0);
	createCanvas(img.width, img.height);
	radius = height / 2;
}

function draw() {
	if (radius > -height / 2) {
		background(0);
		let pos = p5.Vector.random2D().mult(radius);
		let x = pos.x + width / 2;
		let y = pos.y + height / 2;
		if (overlapping(x, y) == false) {
			let shade = img.get(x, y);
			circles.push(new Circle(x, y, 1, shade));
		}
		for (c of circles) {
			c.show();
			if (c.isgrowing) {
				c.grow();
				c.touchesedges();
				for (other of circles) {
					if (c != other) {
						c.touchesother(other);
					}
				}
			}
		}
	}
	radius -= 0.2;
}

function overlapping(x, y) {
	let overlapping = false;
	for (c of circles) {
		var d = dist(x, y, c.x, c.y);
		if (d < c.r) overlapping = true;
	}
	return overlapping;
}
